), t as (
  select v.*,
    case when mode='r' then now() + make_interval(mins => s)
         else (date_trunc('day', now() at time zone 'Europe/London') + make_interval(mins => s)) at time zone 'Europe/London' end st,
    case when mode='r' then now() + make_interval(mins => e)
         else (date_trunc('day', now() at time zone 'Europe/London') + make_interval(mins => e)) at time zone 'Europe/London' end en
  from v)
insert into public.events (title,category,host_name,venue,area,address,lat,lon,start_time,end_time,starts_at,ends_at,description,capacity,price,status)
select title,cat,host,venue,area,venue||', '||area||', London',lat,lon,st,en,st,en,
  case when weekly then 'Every week, same place. ' else title||' — a '||lower(cat)||' session in '||area||'. ' end
    ||'Stress-test listing, safe to delete. #cumulus-stress-test',
  cap,price,'active'
from t
returning id;

