update public.events e set
  venue = m.venue,
  address = m.address,
  area = m.area,
  lat = m.lat,
  lon = m.lon,
  description = case when e.description like 'Every week%'
    then 'Every week at ' || m.venue || ', ' || m.area || '. Stress-test listing, safe to delete. #cumulus-stress-test'
    else e.title || ' — a ' || lower(e.category) || ' session at ' || m.venue || ', ' || m.area || '. Stress-test listing, safe to delete. #cumulus-stress-test' end
from m
where e.description like '%#cumulus-stress-test%'
  and e.venue = m.old_venue and e.area = m.old_area
  and round(e.lat::numeric,5) = round(m.old_lat::numeric,5)
  and round(e.lon::numeric,5) = round(m.old_lon::numeric,5)
returning e.id;